# Clean implementation
def solve_task_issue_1a355150(grid):
    import copy

    # Copy grid, keeping anchor values
    result = [row[:] for row in grid]

    # Find anchors
    anchors = []
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val != 0:
                anchors.append((r, c, val))

    if len(anchors) <= 1:
        return result

    anchor1 = anchors[0] if anchors[0][2] < anchors[1][2] else anchors[1]
    anchor2 = anchors[1] if anchor1 == anchors[0] else anchors[0]

    r1, c1, v1 = anchor1
    r2, c2, v2 = anchor2

    # Output color - from demo it's 3
    # Actually, output color might be the remainder of (v1+v2) or something
    # For demo: v1+1+v2 = 3, or v1+1 = 2+1 = 3
    output_color = 3

    # Bend formula from analysis
    bend_r = r1 + 1
    bend_c = c1 - ((abs(c2 - c1) - 1) // 2)

    # Draw path: from bend to target with slope -1, plus horizontal segment before
    # Bend cell itself
    result[bend_r][bend_c] = output_color

    # Horizontal segment to column = c where diagonal from target intersects bend_row
    # Diagonal from (r2, c2) to (bend_r, c): c = c2 - (bend_r - r2) = c2 - bend_r + r2
    crossing_col = c2 - bend_r + r2
    horizontal_cells = set()
    for c in range(bend_c, crossing_col + 1):
        horizontal_cells.add((bend_r, c))

    for r, c in horizontal_cells:
        result[r][c] = output_color

    # Diagonal from (bend_r, crossing_col) to (r2, c2)
    # With slope -1: c = crossing_col - (r - bend_r) = c2 - bend_r + r2 - (r - bend_r) = c2 + r2 - r
    diagonal_cells = set()
    for r in range(bend_r + 1, r2 + 1):
        c = c2 + r2 - r
        diagonal_cells.add((r, c))

    for r, c in diagonal_cells:
        result[r][c] = output_color

    return result

